#include "ludcmp.h"
#include <string.h>
#include <ap_int.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 8

// Wide bus definitions (replaces ../../../common/mc.h)
#define LARGE_BUS 512
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;
#define DOUBLES_PER_WORD (LARGE_BUS / 64)  // 8 doubles per 512-bit word

// Helper: read doubles from wide bus into local array
static void memcpy_wide_bus_read_double(
    double* dst, int dst_offset,
    const MARS_WIDE_BUS_TYPE* src, long src_byte_offset,
    long byte_len)
{
    int num_doubles = byte_len / sizeof(double);
    long word_offset = src_byte_offset / sizeof(MARS_WIDE_BUS_TYPE);
    int sub_offset = (src_byte_offset % sizeof(MARS_WIDE_BUS_TYPE)) / sizeof(double);

    for (int i = 0; i < num_doubles; i++) {
        #pragma HLS PIPELINE II=1
        int global_idx = sub_offset + i;
        int word_idx = global_idx / DOUBLES_PER_WORD;
        int bit_idx = (global_idx % DOUBLES_PER_WORD) * 64;
        MARS_WIDE_BUS_TYPE word = src[word_offset + word_idx];
        ap_uint<64> bits = word.range(bit_idx + 63, bit_idx);
        double val;
        memcpy(&val, &bits, sizeof(double));
        dst[dst_offset + i] = val;
    }
}

// Helper: write doubles from local array to wide bus
static void memcpy_wide_bus_write_double(
    MARS_WIDE_BUS_TYPE* dst, long dst_byte_offset,
    const double* src, int src_offset,
    long byte_len)
{
    int num_doubles = byte_len / sizeof(double);
    long word_offset = dst_byte_offset / sizeof(MARS_WIDE_BUS_TYPE);
    int sub_offset = (dst_byte_offset % sizeof(MARS_WIDE_BUS_TYPE)) / sizeof(double);

    // For aligned, full-word writes (typical case: N=120, row=120 doubles)
    // Process word by word
    int num_words = (sub_offset + num_doubles + DOUBLES_PER_WORD - 1) / DOUBLES_PER_WORD;
    for (int w = 0; w < num_words; w++) {
        #pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE word = 0;
        for (int d = 0; d < DOUBLES_PER_WORD; d++) {
            int global_idx = w * DOUBLES_PER_WORD + d - sub_offset;
            if (global_idx >= 0 && global_idx < num_doubles) {
                double val = src[src_offset + global_idx];
                ap_uint<64> bits;
                memcpy(&bits, &val, sizeof(double));
                word.range(d * 64 + 63, d * 64) = bits;
            }
        }
        dst[word_offset + w] = word;
    }
}

